def load(f):
    w = wave.open(f,'rb'); n = w.getnframes()
    return np.frombuffer(w.readframes(n), dtype='<i2').reshape(-1, 2), w.getframerate()
def pitch_track(d, rate, step=0.4):
    out=[]
    for t in np.arange(0, len(d)/rate, step):
        seg = d[int(t*rate):int((t+step)*rate),0].astype(float)
        if len(seg)<100 or np.abs(seg).max()<10: out.append((round(t,1),0)); continue
        # zero crossing freq
        zc = np.where(np.diff(np.sign(seg))>0)[0]
        f = len(zc)/(len(seg)/rate)
        out.append((round(t,1), round(f)))
    return out
for f in ['looptest_def','looptest_l2','looptest_s1']:
    d, rate = load(f'/workspace/work/{f}.wav')
    print(f, len(d)/rate, pitch_track(d, rate))
