"""Composer for the keygen tune.  Builds a timeline of tracker events, chops it into
64-row patterns (deduplicated) and emits an ft2 batch file."""
import json, base64, sys
import numpy as np
from synth import build_all

# ---------------------------------------------------------------- basics
BPM, SPEED = 150, 3          # speed 3 -> 8 rows per beat, 32 rows per bar
RPB = 8                      # rows per beat
BAR = 4 * RPB                # 32 rows
PAT_ROWS = 64                # 2 bars per pattern
NCH = 14
KICK, SNARE, HAT, BASS, LEAD, ECHO, STAB, ARP, PAD1, PAD2, PAD3, HARM, FX, PERC = range(NCH)
I_KICK, I_SNARE, I_HC, I_HO, I_BASS, I_LEAD, I_STAB, I_ARP, I_PAD, I_CRASH, I_TOM, I_RISER, I_CLAP, I_HARM = range(1, 15)

NOTE_IDX = {'C':0,'C#':1,'D':2,'D#':3,'E':4,'F':5,'F#':6,'G':7,'G#':8,'A':9,'A#':10,'B':11}
def n(name):
    """'F#5' -> XM note number (C-4 = 49)"""
    if name[1] == '#': p, o = name[:2], int(name[2:])
    else: p, o = name[:1], int(name[1:])
    return 12 * o + NOTE_IDX[p] + 1
OFF = 97
def V(v): return 0x10 + max(0, min(64, int(v)))      # volume column: set volume

CHORDS = {   # name: (root pitch class name, [intervals])
    'Em': ('E', [0, 3, 7]), 'C': ('C', [0, 4, 7]), 'G': ('G', [0, 4, 7]), 'D': ('D', [0, 4, 7]),
    'Am': ('A', [0, 3, 7]), 'B': ('B', [0, 4, 7]), 'Bm': ('B', [0, 3, 7]),
}
def chord_tones(ch, octave):
    root, iv = CHORDS[ch]
    r = n(f"{root}{octave}")
    return [r + i for i in iv]
def chord_root(ch, octave):
    return n(f"{CHORDS[ch][0]}{octave}")
def arp_param(ch):
    iv = CHORDS[ch][1]
    return (iv[1] << 4) | iv[2]

E_MINOR = [n('E4') % 12, n('F#4') % 12, n('G4') % 12, n('A4') % 12, n('B4') % 12, n('C4') % 12, n('D4') % 12]
def third_below(note):
    """diatonic third below in E minor"""
    pc = (note - 1) % 12
    scale = sorted(E_MINOR)
    if pc not in scale: return note - 3
    i = scale.index(pc)
    j = (i - 2) % 7
    down = (pc - scale[j]) % 12
    return note - down

# ---------------------------------------------------------------- song container
class Song:
    def __init__(self):
        self.cells = {}          # (row, ch) -> dict
    def put(self, row, ch, note=None, inst=None, vol=None, eff=None, par=None):
        c = self.cells.setdefault((row, ch), {})
        if note is not None: c['note'] = note
        if inst is not None: c['instrument'] = inst
        if vol is not None: c['volume'] = vol
        if eff is not None:
            c['effect'] = eff; c['effect_param'] = par or 0
    def get(self, row, ch):
        return self.cells.get((row, ch))
    def max_row(self):
        return max(r for r, _ in self.cells)

S = Song()

# ---------------------------------------------------------------- melody parsing
def parse_melody(bars):
    """list of bar strings with 16 tokens each -> list of (slot_index, token)"""
    ev = []
    for b, s in enumerate(bars):
        toks = s.split()
        assert len(toks) == 16, (b, s, len(toks))
        for i, t in enumerate(toks):
            ev.append((b * 16 + i, t))
    return ev

def write_melody(row0, bars, ch, inst, vol, vib=0x62, vib_after=4, transpose=0, harmony=None, hvol=None, hch=None):
    ev = parse_melody(bars)
    # figure out durations to place vibrato on long notes
    i = 0
    while i < len(ev):
        slot, t = ev[i]
        if t == '-':
            i += 1; continue
        row = row0 + slot * 2
        if t == '.':
            S.put(row, ch, note=OFF)
            if harmony is not None: S.put(row, hch, note=OFF)
            i += 1; continue
        note = n(t) + transpose
        S.put(row, ch, note=note, inst=inst, vol=V(vol))
        if harmony is not None:
            S.put(row, hch, note=harmony(note), inst=I_HARM, vol=V(hvol))
        # duration in slots
        j = i + 1
        while j < len(ev) and ev[j][1] == '-': j += 1
        dur = (ev[j][0] if j < len(ev) else ev[-1][0] + 1) - slot
        if vib and dur >= vib_after:
            for k in range(2 * 2, dur * 2):     # start vibrato after 2 slots (4 rows)
                S.put(row + k, ch, eff=4, par=vib)
        i += 1

def echo_copy(row_lo, row_hi, src, dst, delay, gain, pans=(0x40, 0xC0)):
    """copy channel src rows [row_lo,row_hi) to dst shifted by delay with reduced volume and ping-pong pan"""
    k = 0
    for (r, c), cell in sorted(S.cells.items()):
        if c != src or not (row_lo <= r < row_hi): continue
        d = dict(cell)
        if 'volume' in d:
            d['volume'] = V(round((d['volume'] - 0x10) * gain))
        if 'note' in d and d['note'] != OFF:
            d['effect'], d['effect_param'] = 8, pans[k % 2]; k += 1
        S.put(r + delay, dst, d.get('note'), d.get('instrument'), d.get('volume'), d.get('effect'), d.get('effect_param'))

# ---------------------------------------------------------------- drums
def hat_vol(r):
    if r % 8 == 0: return 0x2a
    if r % 4 == 0: return 0x22
    return 0x16

def drums_bar(row0, style, fill=False, ghost=False):
    K = {'A': [0, 16, 28], 'B': [0, 12, 16, 28], 'four': [0, 8, 16, 24], 'one': [0], 'half': [0, 16],
         'C': [0, 10, 16, 24]}[style]
    if fill: K = [0, 16]
    for r in K: S.put(row0 + r, KICK, n('C4'), I_KICK, V(60))
    if style in ('A', 'B', 'C'):
        for r in (8, 24):
            S.put(row0 + r, SNARE, n('C4'), I_SNARE, V(52))
        if style in ('B', 'C'):
            for r in (8, 24):
                S.put(row0 + r, PERC, n('C4'), I_CLAP, V(34))
        if ghost:
            S.put(row0 + 30, SNARE, n('C4'), I_SNARE, V(22))
        opens = {'A': [4, 12, 20, 28], 'B': [4, 20], 'C': [4, 12, 20]}[style]
        for r in range(0, BAR, 2):
            if r in opens:
                S.put(row0 + r, HAT, n('C4'), I_HO, V(0x22))
            else:
                S.put(row0 + r, HAT, n('C4'), I_HC, V(hat_vol(r)))
    if fill:
        # tom run then snare 16ths into the downbeat
        for r, note in zip((18, 20, 22), ('E4', 'C4', 'A3')):
            S.put(row0 + r, PERC, n(note), I_TOM, V(44))
        for i, r in enumerate((24, 26, 28, 30)):
            S.put(row0 + r, SNARE, n('C4'), I_SNARE, V(36 + 6 * i))
        for r in range(0, BAR, 2):
            if r < 24 and S.get(row0 + r, HAT) is None:
                S.put(row0 + r, HAT, n('C4'), I_HC, V(hat_vol(r)))

def snare_roll(row0, start, vol0=20, vol1=60, step=1):
    rows = list(range(start, BAR, step))
    for i, r in enumerate(rows):
        v = vol0 + (vol1 - vol0) * i / max(1, len(rows) - 1)
        S.put(row0 + r, SNARE, n('C4'), I_SNARE, V(v))

# ---------------------------------------------------------------- bass
def bass_bar(row0, ch, style, next_ch=None):
    r2 = chord_root(ch, 2)
    r3 = r2 + 12
    if style == 'pump':          # root / octave alternation, 8ths
        seq = [(0, r2), (4, r3), (8, r2), (12, r3), (16, r2), (20, r3), (24, r2), (28, r3)]
        vols = [50, 40, 46, 40, 50, 40, 46, 40]
    elif style == 'drive':       # syncopated with 16th pushes
        seq = [(0, r2), (6, r2), (8, r3), (12, r2), (16, r2), (22, r2), (24, r3), (28, r2), (30, r2 + 7 if next_ch is None else chord_root(next_ch, 2) - 1)]
        vols = [50, 40, 44, 42, 50, 40, 44, 42, 38]
    elif style == 'long':        # sustained root, re-hit at beat 3
        seq = [(0, r2), (16, r2)]
        vols = [48, 40]
    elif style == 'half':
        seq = [(0, r2), (8, r2), (16, r2), (24, r2)]
        vols = [50, 40, 46, 40]
    else:
        raise ValueError(style)
    for (r, note), v in zip(seq, vols):
        S.put(row0 + r, BASS, note, I_BASS, V(v))

# ---------------------------------------------------------------- chords / arps
def stabs_bar(row0, ch, pattern, vol=40):
    par = arp_param(ch)
    root = chord_root(ch, 4)
    pats = {
        '8ths': [(r, vol if r % 8 == 0 else vol - 10) for r in range(0, BAR, 4)],
        'sync': [(0, vol), (6, vol - 10), (12, vol - 6), (16, vol), (22, vol - 10), (26, vol - 8), (28, vol - 4)],
        'off':  [(4, vol), (12, vol - 6), (20, vol), (28, vol - 6)],
        'hold': [(0, vol), (16, vol - 6)],
    }[pattern]
    for r, v in pats:
        S.put(row0 + r, STAB, root, I_STAB, V(v), 0, par)

def arp_bar(row0, ch, shape, vol=36, octave=4, accent=(6, -2, 2, -2)):
    T = chord_tones(ch, octave) + chord_tones(ch, octave + 1)
    shapes = {
        'updown': [0, 1, 2, 3, 4, 5, 4, 3, 2, 1, 0, 1, 2, 3, 4, 3],
        'bounce': [0, 3, 1, 4, 2, 5, 1, 4] * 2,
        'up':     [0, 1, 2, 3, 4, 5, 3, 4] * 2,
        'wide':   [0, 2, 3, 5, 3, 2, 0, 2, 1, 3, 4, 5, 4, 3, 1, 3],
    }[shape]
    for i, idx in enumerate(shapes):
        S.put(row0 + 2 * i, ARP, T[idx], I_ARP, V(vol + accent[i % 4]))

def arp_8ths_bar(row0, ch, vol=30, octave=4):
    T = chord_tones(ch, octave) + chord_tones(ch, octave + 1)
    seq = [0, 2, 3, 5, 4, 3, 2, 1]
    for i, idx in enumerate(seq):
        S.put(row0 + 4 * i, ARP, T[idx], I_ARP, V(vol + (4 if i % 2 == 0 else 0)))

def pad_bar(row0, ch, vol=26, retrigger=True, octave=3):
    tones = chord_tones(ch, octave)
    # spread: root (oct 3), third (oct 4), fifth (oct 4) for an open voicing
    voicing = [tones[0], tones[1] + 12, tones[2]]
    for c, note in zip((PAD1, PAD2, PAD3), voicing):
        S.put(row0, c, note, I_PAD, V(vol))

def pads_off(row):
    for c in (PAD1, PAD2, PAD3):
        S.put(row, c, note=OFF)

# ---------------------------------------------------------------- melodies
MEL_A = [
    "E5 - - G5 - - B5 - - - A5 - G5 - F#5 -",
    "E5 - - G5 - - C6 - - - B5 - A5 - G5 -",
    "D5 - - G5 - - B5 - - - A5 - B5 - D6 -",
    "C6 - - B5 - - A5 - - - F#5 - - - - -",
    "E5 - - G5 - - B5 - - - A5 - G5 - F#5 -",
    "E5 - - G5 - - C6 - - - B5 - A5 - G5 -",
    "D5 - - G5 - - B5 - - - D6 - - - E6 -",
    "D6 - - A5 - - F#5 - - - A5 - - - . .",
]
MEL_B = [
    "A5 - - - C6 - - - E6 - - - - - D6 -",
    "B5 - - - - - - - G5 - - - - - A5 -",
    "C6 - - - E6 - - - G6 - - - - - E6 -",
    "D6 - - - - - - - F#5 - - - A5 - - -",
    "A5 - - - C6 - - - E6 - - - - - D6 -",
    "B5 - - - - - - - G5 - - - - - A5 -",
    "C6 - - - B5 - - - A5 - - - G5 - - -",
    "F#5 - - - - - - - D#5 - - - - - . .",
]
MEL_BREAK = [
    "E5 - - - B4 - - - E5 - - - G5 - - -",
    "G5 - - - E5 - - - C5 - - - E5 - - -",
    "D5 - - - B4 - - - G4 - - - B4 - - -",
    "A4 - - - - - - - F#4 - - - A4 - - -",
    "E5 - - - B4 - - - E5 - - - G5 - - -",
    "G5 - - - E5 - - - C5 - - - E5 - - -",
    "A4 - - - C5 - - - E5 - - - A5 - - -",
    "B5 - - - - - - - F#5 - - - D#5 - . .",
]
MEL_TURN = [
    "E5 - - G5 - - B5 - - - E6 - - - - -",
    "E6 - - C6 - - G5 - - - E5 - - - . .",
    "E6 D6 C6 B5 A5 G5 F#5 E5 D5 - - - F#5 - A5 -",
    "B5 - - - F#5 - - - D#5 - - - - - . .",
]

# ---------------------------------------------------------------- sections
PROG_A = ['Em', 'C', 'G', 'D', 'Em', 'C', 'G', 'D']
PROG_B = ['Am', 'Em', 'C', 'D', 'Am', 'Em', 'C', 'B']
PROG_BREAK = ['Em', 'C', 'G', 'D', 'Em', 'C', 'Am', 'B']
PROG_TURN = ['Em', 'C', 'D', 'B']

def sec_intro(bar0):
    r0 = bar0 * BAR
    for i, ch in enumerate(PROG_A):
        rb = r0 + i * BAR
        pad_bar(rb, ch, vol=30 if i < 4 else 26)
        if i < 2:
            arp_8ths_bar(rb, ch, vol=26)
        else:
            arp_bar(rb, ch, 'up', vol=28 + 2 * (i - 2) // 2)
        if i >= 4:
            for r in range(0, BAR, 4):
                S.put(rb + r, HAT, n('C4'), I_HC, V(hat_vol(r) - 4))
        if i >= 6:
            for r in (0, 8, 16, 24):
                S.put(rb + r, KICK, n('C4'), I_KICK, V(52))
            bass_bar(rb, ch, 'half')
    # theme teaser with the soft voice, echoed
    write_melody(r0 + 4 * BAR, MEL_A[:4], HARM, I_HARM, 30, vib=0x52)
    echo_copy(r0 + 4 * BAR, r0 + 8 * BAR, HARM, ECHO, 6, 0.45)
    # riser + snare build in the last two bars
    S.put(r0 + 6 * BAR, FX, n('C4'), I_RISER, V(30))
    snare_roll(r0 + 7 * BAR, 16, 16, 58, 2)
    for i, r in enumerate((24, 26, 28, 30)):
        S.put(r0 + 7 * BAR + r, SNARE, n('C4'), I_SNARE, V(46 + 5 * i))
    pads_off(r0 + 8 * BAR - 1) if False else None

def sec_A(bar0, harmony=False, pads=False):
    r0 = bar0 * BAR
    S.put(r0, FX, n('C4'), I_CRASH, V(40))
    for i, ch in enumerate(PROG_A):
        rb = r0 + i * BAR
        last = (i == 7)
        drums_bar(rb, 'A', fill=last and harmony, ghost=(i % 2 == 1))
        if last and not harmony:
            snare_roll(rb, 24, 30, 56, 2)
        bass_bar(rb, ch, 'pump' if i % 4 != 3 else 'drive', PROG_A[(i + 1) % 8])
        stabs_bar(rb, ch, '8ths', vol=36)
        arp_bar(rb, ch, 'updown', vol=34)
        if pads: pad_bar(rb, ch, vol=20)
    if harmony:
        write_melody(r0, MEL_A, LEAD, I_LEAD, 46, harmony=third_below, hvol=30, hch=HARM)
    else:
        write_melody(r0, MEL_A, LEAD, I_LEAD, 46)
    echo_copy(r0, r0 + 8 * BAR, LEAD, ECHO, 6, 0.42)

def sec_B(bar0):
    r0 = bar0 * BAR
    for i, ch in enumerate(PROG_B):
        rb = r0 + i * BAR
        drums_bar(rb, 'B', fill=(i == 7), ghost=(i % 2 == 1))
        bass_bar(rb, ch, 'drive' if i % 2 == 0 else 'pump', PROG_B[(i + 1) % 8])
        stabs_bar(rb, ch, 'sync', vol=36)
        arp_bar(rb, ch, 'bounce', vol=32)
        pad_bar(rb, ch, vol=20)
    write_melody(r0, MEL_B, LEAD, I_LEAD, 46, vib=0x63)
    echo_copy(r0, r0 + 8 * BAR, LEAD, ECHO, 6, 0.42)

def sec_break(bar0):
    r0 = bar0 * BAR
    S.put(r0, FX, n('C4'), I_CRASH, V(34))
    for i, ch in enumerate(PROG_BREAK):
        rb = r0 + i * BAR
        pad_bar(rb, ch, vol=32)
        arp_bar(rb, ch, 'wide', vol=26 if i < 4 else 30)
        bass_bar(rb, ch, 'long' if i < 4 else 'half')
        if i < 4:
            S.put(rb, KICK, n('C4'), I_KICK, V(50))
        else:
            for r in (0, 8, 16, 24):
                S.put(rb + r, KICK, n('C4'), I_KICK, V(54))
            for r in range(0, BAR, 4):
                S.put(rb + r, HAT, n('C4'), I_HC, V(hat_vol(r) - 2))
            if i >= 6:
                stabs_bar(rb, ch, 'off', vol=30)
    write_melody(r0, MEL_BREAK, HARM, I_HARM, 40, vib=0x52)
    echo_copy(r0, r0 + 8 * BAR, HARM, ECHO, 6, 0.45)
    S.put(r0 + 6 * BAR, FX, n('C4'), I_RISER, V(34))
    snare_roll(r0 + 7 * BAR, 0, 10, 60, 2)
    for r in range(24, 32):
        S.put(r0 + 7 * BAR + r, SNARE, n('C4'), I_SNARE, V(48 + (r - 24) * 2))
    pads_off(r0 + 8 * BAR - 1) if False else None

def sec_turn(bar0):
    r0 = bar0 * BAR
    for i, ch in enumerate(PROG_TURN):
        rb = r0 + i * BAR
        drums_bar(rb, 'C', fill=(i == 3), ghost=(i == 1))
        bass_bar(rb, ch, 'drive' if i < 3 else 'half', PROG_TURN[(i + 1) % 4])
        stabs_bar(rb, ch, 'sync' if i < 3 else 'hold', vol=38)
        arp_bar(rb, ch, 'updown', vol=32)
        pad_bar(rb, ch, vol=20)
    write_melody(r0, MEL_TURN, LEAD, I_LEAD, 46)
    echo_copy(r0, r0 + 4 * BAR, LEAD, ECHO, 6, 0.42)
    # final bar: snare build under the held D#
    snare_roll(r0 + 3 * BAR, 16, 30, 60, 2)

# ---------------------------------------------------------------- arrangement
LAYOUT = [('intro', 8), ('A', 8), ('B', 8), ('break', 8), ('A2', 8), ('turn', 4)]
bar = 0
loop_bar = None
for name, length in LAYOUT:
    if name == 'intro': sec_intro(bar)
    elif name == 'A': loop_bar = bar; sec_A(bar)
    elif name == 'B': sec_B(bar)
    elif name == 'break': sec_break(bar)
    elif name == 'A2': sec_A(bar, harmony=True, pads=True)
    elif name == 'turn': sec_turn(bar)
    bar += length
TOTAL_ROWS = bar * BAR
assert TOTAL_ROWS % PAT_ROWS == 0
NPAT_POS = TOTAL_ROWS // PAT_ROWS
LOOP_POS = loop_bar * BAR // PAT_ROWS

# drop anything that spilled past the end (echo tails) -> wrap to loop start? no: just cut
for key in [k for k in S.cells if k[0] >= TOTAL_ROWS]:
    del S.cells[key]

# ---------------------------------------------------------------- chop into patterns
def pattern_key(pos):
    items = []
    for (r, c), cell in S.cells.items():
        if pos * PAT_ROWS <= r < (pos + 1) * PAT_ROWS:
            items.append((r - pos * PAT_ROWS, c, tuple(sorted(cell.items()))))
    return tuple(sorted(items))

order = []
pat_of_key = {}
patterns = []
for pos in range(NPAT_POS):
    k = pattern_key(pos)
    if k not in pat_of_key:
        pat_of_key[k] = len(patterns)
        patterns.append(k)
    order.append(pat_of_key[k])

# ---------------------------------------------------------------- batch
PANS = {I_KICK: 128, I_SNARE: 120, I_HC: 168, I_HO: 168, I_BASS: 128, I_LEAD: 128, I_STAB: 178, I_ARP: 78,
        I_PAD: 128, I_CRASH: 128, I_TOM: 100, I_RISER: 128, I_CLAP: 88, I_HARM: 128}
calls = [{"name": "module_new", "arguments": {"channels": NCH, "name": "keygen groove"}}]
insts = build_all()
for num, (name, pcm, meta) in insts.items():
    b64 = base64.b64encode(pcm.tobytes()).decode()
    calls.append({"name": "sample_create_from_pcm", "arguments": {"instrument": num, "sample": 0, "pcm": b64, "encoding": "int16", "name": name[:22]}})
    ll = meta.get('loop_length', 0)
    flags = 16 | (1 if ll > 0 else 0)
    calls.append({"name": "sample_set", "arguments": {"instrument": num, "sample": 0, "volume": 64, "panning": PANS[num],
                                                      "relative_note": meta.get('relative_note', 0), "finetune": 0,
                                                      "loop_start": meta.get('loop_start', 0), "loop_length": ll, "flags": flags}})
    calls.append({"name": "instrument_set", "arguments": {"instrument": num, "name": name[:22]}})
for p, key in enumerate(patterns):
    calls.append({"name": "pattern_set_length", "arguments": {"pattern": p, "rows": PAT_ROWS}})
    for r, c, items in key:
        args = {"pattern": p, "row": r, "channel": c}
        args.update(dict(items))
        calls.append({"name": "pattern_set_cell", "arguments": args})
